commands.command:
location = /salud { return 200 "ok\n"; }
location ^~ /static/ { root /var/www/app; }
location ~* \.php$ { return 403; }
location / { proxy_pass http://127.0.0.1:8000; }

examples.code:
location /api/ {
    add_header X-Ruta "api" always;
    proxy_pass http://127.0.0.1:8000;
}

server {
    listen 80;
    server_name viejo.cl;
    return 301 https://nuevo.cl$request_uri;
}

